#!/usr/bin/env python3
"""
gateway_debug.py
Tests TCP connections to ports 8080, 8443, and 3128 on the default gateway.
"""

import socket
import subprocess
import sys

PORTS = [8080, 8443, 3128]
TIMEOUT = 3  # seconds


def get_default_gateway() -> str:
    """Retrieve the default gateway IP address."""
    try:
        # Linux: parse /proc/net/route
        with open("/proc/net/route") as f:
            for line in f.readlines()[1:]:
                fields = line.strip().split()
                if fields[1] == "00000000" and fields[7] == "00000000":
                    # Destination is 0.0.0.0 → this is the default route
                    gw_hex = fields[2]
                    # Convert little-endian hex to dotted-decimal
                    gw_int = int(gw_hex, 16)
                    gw_ip = socket.inet_ntoa(gw_int.to_bytes(4, "little"))
                    return gw_ip
    except FileNotFoundError:
        pass

    # Fallback: use `ip route` command
    try:
        output = subprocess.check_output(
            ["ip", "route", "show", "default"], text=True
        )
        for token in output.split():
            if token.count(".") == 3:
                return token
    except Exception:
        pass

    # macOS / BSD fallback: netstat -rn
    try:
        output = subprocess.check_output(
            ["netstat", "-rn"], text=True
        )
        for line in output.splitlines():
            parts = line.split()
            if parts and parts[0] in ("default", "0.0.0.0"):
                for part in parts[1:]:
                    if part.count(".") == 3:
                        return part
    except Exception:
        pass

    return None


def test_tcp(host: str, port: int, timeout: int = TIMEOUT) -> tuple[bool, str]:
    """Attempt a TCP connection. Returns (success, message)."""
    try:
        with socket.create_connection((host, port), timeout=timeout):
            return True, "OPEN"
    except socket.timeout:
        return False, "TIMEOUT"
    except ConnectionRefusedError:
        return False, "REFUSED"
    except OSError as e:
        return False, f"ERROR ({e})"


def main():
    print("=" * 50)
    print("Gateway TCP Connection Debugger")
    print("=" * 50)

    gateway = get_default_gateway()
    if not gateway:
        print("[!] Could not determine the default gateway. Exiting.")
        sys.exit(1)

    print(f"[*] Default gateway: {gateway}")
    print(f"[*] Testing ports:   {', '.join(str(p) for p in PORTS)}")
    print(f"[*] Timeout:         {TIMEOUT}s per port")
    print("-" * 50)

    results = []
    for port in PORTS:
        success, status = test_tcp(gateway, port)
        icon = "✓" if success else "✗"
        print(f"  {icon}  {gateway}:{port:<6}  →  {status}")
        results.append((port, success, status))

    print("-" * 50)
    open_ports = [str(p) for p, ok, _ in results if ok]
    closed_ports = [str(p) for p, ok, _ in results if not ok]

    if open_ports:
        print(f"[+] Open/reachable:  {', '.join(open_ports)}")
    if closed_ports:
        print(f"[-] Closed/blocked:  {', '.join(closed_ports)}")

    print("=" * 50)


if __name__ == "__main__":
    main()

