def test_tcp(host: str, port: int, timeout: int = TIMEOUT) -> tuple[bool, str, float]:
    """Attempt a TCP connection. Returns (success, message, elapsed_ms)."""
    t0 = time.perf_counter()
    try:
        with socket.create_connection((host, port), timeout=timeout):
            elapsed = (time.perf_counter() - t0) * 1000
            return True, "OPEN", elapsed
    except socket.timeout:
        elapsed = (time.perf_counter() - t0) * 1000
        return False, "TIMEOUT", elapsed
    except ConnectionRefusedError:
        elapsed = (time.perf_counter() - t0) * 1000
        return False, "REFUSED", elapsed
    except OSError as e:
        elapsed = (time.perf_counter() - t0) * 1000
        return False, f"ERROR ({e})", elapsed
